// Checks the generated landing pages: one per app page in shared/apps.js (/apps/<id>/), plus /slop-365/,
// /creative-slop-pro/ and /compare/. Reads the files on disk (no browser). Run with: node tests/run.mjs seo
// Each app page needs one H1 (the registry title), an "Open now" link to the app, a feature matrix with
// exactly the registry features, a description of 120 to 160 characters, a canonical URL, and a sitemap entry.
// Generated by tools/seo/landing.mjs and tools/seo/write.mjs.
// Covers: shared/seo/copy.mjs, shared/seo/landing-copy.mjs
import { test } from 'node:test';
import assert from 'node:assert/strict';
import path from 'node:path';
import { existsSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { loadRegistry, isPage, SITE, ROOT } from '../../tools/seo/site.mjs';
import { esc, fileTypeList, related, SLOP365, STATUS, regWords } from '../../tools/seo/landing.mjs';
import { context, ROOT_LANG } from '../../tools/seo/lang.mjs';

/** The root language's words (the profile's defaultLang: a build can have another than English at the root). */
const R = context(ROOT_LANG), say = (k, v) => esc(R.t(k, v));

const read = (rel) => readFile(path.join(ROOT, rel), 'utf8');
const apps = await loadRegistry();
const pageApps = apps.filter(isPage);
const HUBS = [
  { id: 'slop-365', dir: 'slop-365/' },
  { id: 'creative-slop-pro', dir: 'creative-slop-pro/' },
  { id: 'compare', dir: 'compare/' },
];
const pages = [
  ...pageApps.map((a) => ({ id: a.id, dir: `apps/${a.id}/`, app: a })),
  ...HUBS.map((h) => ({ ...h, app: null })),
];
const html = {};
for (const p of pages) p.url = `${SITE}/${p.dir}`;
const found = pages.filter((p) => existsSync(path.join(ROOT, p.dir, 'index.html')));
for (const p of found) html[p.id] = await read(path.join(p.dir, 'index.html'));
const meta = (h, re) => { const m = h.match(re); return m ? m[1] : null; };
const h1Of = (h) => [...h.matchAll(/<h1>([^<]*)<\/h1>/g)].map((m) => m[1]);
const descOf = (h) => meta(h, /<meta\s+name="description"\s+content="([^"]*)"/);
const canonicalOf = (h) => meta(h, /<link\s+rel="canonical"\s+href="([^"]*)"/);
/** The feature matrix rows: [feature, status, file types] for the table in one page. */
const rowsOf = (h) => [...h.matchAll(/<tr><td>([^<]*)<\/td><td>([^<]*)<\/td><td>([^<]*)<\/td><\/tr>/g)].map((m) => m.slice(1, 4));

test('every app page in the registry has a landing page', () => {
  for (const a of pageApps) assert.ok(html[a.id], `${a.id}: no landing page at apps/${a.id}/index.html`);
  for (const h of HUBS) assert.ok(html[h.id], `${h.id}: no page at ${h.dir}index.html`);
});

test('each landing page has exactly one H1 with the registry title', () => {
  for (const a of pageApps) {
    if (!html[a.id]) continue;
    assert.deepEqual(h1Of(html[a.id]), [esc(regWords(a, R).title)], `${a.id}: H1`);
  }
});

test('each app landing page has an Open now button to the app folder', () => {
  for (const a of pageApps) {
    if (!html[a.id]) continue;
    assert.ok(html[a.id].includes(`<a class="btn" href="/${a.path}" aria-label="${say('seo.ui.app.open_now_label', { app: a.name })}">${say('seo.ui.app.open_now')}</a>`), `${a.id}: Open now link to /${a.path}`);
    assert.ok(existsSync(path.join(ROOT, a.path, 'index.html')), `${a.id}: the app folder ${a.path} has no index.html`);
  }
});

// the lengths (120 to 160) are this site's copy: tests/seo/site-copy.test.mjs (repo-only; a build's renamed copy differs)
test('each landing page has a description, unique, and a canonical URL', () => {
  const seen = new Map();
  for (const p of found) {
    const d = descOf(html[p.id]);
    assert.ok(d, `${p.id}: no meta description`);
    assert.ok(!seen.has(d), `${p.id}: description repeats ${seen.get(d)}`);
    seen.set(d, p.id);
    assert.equal(canonicalOf(html[p.id]), p.url, `${p.id}: canonical`);
  }
});

test('each feature matrix lists exactly the registry features, with status and file types', () => {
  for (const a of pageApps) {
    if (!html[a.id]) continue;
    const rows = rowsOf(html[a.id]);
    const feats = regWords(a, R).features; // copied out of the VM realm the registry is loaded in
    const types = fileTypeList(a, R).map(esc).join(', ') || say('seo.ui.type.none');
    if (!feats.length) { assert.ok(html[a.id].includes(say('seo.ui.app.no_features')), `${a.id}: empty matrix note`); continue; }
    assert.deepEqual(rows.map((r) => r[0]), feats.map(esc), `${a.id}: feature rows`);
    for (const r of rows) assert.deepEqual(r.slice(1), [STATUS[a.status || 'live'], types], `${a.id}: status and file types`);
  }
});

test('each app landing page links to related landing pages, never to itself', () => {
  for (const a of pageApps) {
    if (!html[a.id]) continue;
    const rel = related(a, apps);
    assert.ok(rel.length >= 1 && rel.length <= 6, `${a.id}: ${rel.length} related apps`);
    assert.ok(!rel.some((b) => b.id === a.id), `${a.id}: lists itself`);
    for (const b of rel) assert.ok(html[a.id].includes(`href="/apps/${b.id}/"`), `${a.id}: missing related link to ${b.id}`);
  }
});

test('the landing pages are in sitemap.xml with a lastmod date', async () => {
  const xml = await read('sitemap.xml');
  const locs = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]);
  for (const p of pages) assert.ok(locs.includes(p.url), `sitemap is missing ${p.url}`);
  for (const m of xml.matchAll(/<url>[\s\S]*?<\/url>/g)) if (/\/apps\/|\/slop-365\/|\/creative-slop-pro\/|\/compare\//.test(m[0])) assert.match(m[0], /<lastmod>\d{4}-\d{2}-\d{2}<\/lastmod>/);
});

test('the compare page lists every app page with a link and its file types', () => {
  const h = html.compare;
  assert.ok(h, 'no compare page');
  assert.equal(h1Of(h).length, 1, 'compare: one H1');
  for (const a of pageApps) assert.ok(h.includes(`href="/apps/${a.id}/"`), `compare: missing ${a.id}`);
  assert.ok(h.includes(say('seo.ui.cmp.lead', { n: pageApps.length })), 'compare: app count in the intro');
});

test('the Slop 365 page links to each of its tools', () => {
  const h = html['slop-365'];
  assert.ok(h, 'no Slop 365 page');
  for (const id of SLOP365) {
    assert.ok(apps.some((a) => a.id === id), `Slop 365 lists ${id}, which is not in the registry`);
    assert.ok(h.includes(`href="/apps/${id}/"`), `slop-365: missing ${id}`);
  }
});

test('the Creative Slop Pro page names the three apps and says it is not affiliated with Adobe', () => {
  const h = html['creative-slop-pro'];
  assert.ok(h, 'no Creative Slop Pro page');
  for (const id of ['photoslop', 'vector', 'slopedit']) assert.ok(h.includes(`href="/apps/${id}/"`), `creative: missing ${id}`);
  for (const k of ['lead', 'not_1', 'not_2', 'not_3']) assert.ok(h.includes(say('seo.ui.csp.' + k)), `creative: ${k}`);
  if (ROOT_LANG === 'en') {   // the English words, as this site says them
    assert.match(h, /free browser alternative to Photoshop-style photo editing, Illustrator-style vector drawing and video editing/);
    assert.match(h, /not affiliated with, endorsed by or sponsored by Adobe/);
    assert.match(h, /do not run the full feature sets/);
  }
});
